        var camera=new GameObject("Main Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.orthographic=true;camera.orthographicSize=6.8f;camera.transform.position=new Vector3(13,18,-21);camera.transform.LookAt(new Vector3(0,.3f,-1.5f));camera.rect=new Rect(0,.13f,1,.77f);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.77f,.9f,.88f);camera.nearClipPlane=.1f;camera.farClipPlane=80;
        var light=new GameObject("Sunlight").AddComponent<Light>();light.type=LightType.Directional;light.intensity=.8f;light.transform.rotation=Quaternion.Euler(55,-30,0);light.shadows=LightShadows.Soft;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.42f,.45f,.48f);
        Color[] colors={new Color(.48f,.72f,.49f),new Color(.86f,.82f,.68f),new Color(.4f,.46f,.5f),new Color(.75f,.8f,.76f),new Color(.98f,.97f,.91f),new Color(1,.71f,.32f),new Color(.94f,.44f,.37f),new Color(.35f,.72f,.85f),new Color(.69f,.5f,.8f),new Color(.47f,.72f,.54f),new Color(.22f,.59f,.49f),new Color(.68f,.8f,.82f),new Color(.71f,.57f,.4f),new Color(.24f,.3f,.32f),new Color(.84f,.75f,.61f),new Color(1,.82f,.65f)};
        var root=new GameObject("Konbini");var view=root.AddComponent<StoreView>();view.cameraView=camera;view.japanese=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/NotoSansCJKjp-Regular.otf");if(!view.japanese)throw new Exception("Japanese font not imported");view.materials=new Material[colors.Length];for(int i=0;i<colors.Length;i++){string file="Assets/Materials/Town"+i+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(file);if(!mat){mat=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(mat,file);}mat.color=colors[i];mat.SetFloat("_Glossiness",.05f);view.materials[i]=mat;}
